mapper.select:
select
id, moment_id, reply_type, to_id, parent_id, to_user, to_user_author, reply_id, reply_user, reply_author,
content, pic_urls, created_by, created_time, update_by, update_time, is_deleted
from share_comment_reply


        and id = #{id}


        and moment_id = #{momentId}


        and reply_type = #{replyType}


        and to_id = #{toId}


        and parent_id = #{parentId}


        and to_user = #{toUser}


        and to_user_author = #{toUserAuthor}


        and reply_id = #{replyId}


        and reply_user = #{replyUser}


        and reply_author = #{replyAuthor}


        and content = #{content}


        and pic_urls = #{picUrls}


        and created_by = #{createdBy}


        and created_time = #{createdTime}


        and update_by = #{updateBy}


        and update_time = #{updateTime}


        and is_deleted = #{isDeleted}


limit #{pageable.offset}, #{pageable.pageSize}

select count(1)
from share_comment_reply


        and id = #{id}


        and moment_id = #{momentId}


        and reply_type = #{replyType}


        and to_id = #{toId}


